def analyze(ss, atg):
    pos=atg; first=[]
    while pos+3<=len(ss):
        aa=codon.get(ss[pos:pos+3],"X")
        if aa=="*": break
        first.append(aa); pos+=3
    stop_pos=pos
    res=[]
    # walk again, try shifts
    pos=atg; prot=[]
    while pos+3<=len(ss):
        aa=codon.get(ss[pos:pos+3],"X")
        if aa=="*": break
        for delta in (-1,1):
            ns=pos+delta; p2=[];q=ns
            while q+3<=len(ss):
                a2=codon.get(ss[q:q+3],"X")
                if a2=="*": break
                p2.append(a2); q+=3
            res.append((len(prot),pos,delta,len(p2),stop_pos))
        prot.append(aa); pos+=3
    return len(first), stop_pos, res

